from helpers import *
W=week(HRS,{"quant":["Profit & Loss","Discount"],"reasoning":["Coding-Decoding","Alphabet"],"english":["Articles","Prepositions","Error Spotting"],"ga":["Polity"]},
unit("Quant: Profit & loss, discount",[
 part("Part 1: Profit and loss basics",
  [rd(RSA,"Chapter 'Profit and Loss': theory and solved examples"),rd(KM,"Chapter 'Profit and Loss': first 10 solved questions")],
  ["Profit = SP − CP. Loss = CP − SP. Profit % and Loss % are always on CP.",
   "SP = CP × (100 + P)/100 for profit, CP × (100 − L)/100 for loss. CP = SP × 100/(100 ± %).",
   "Fraction trick: profit 25% = 1/4, so SP : CP = 5 : 4. Profit 12.5% = 1/8, so SP : CP = 9 : 8. Loss 20% = 1/5, so SP : CP = 4 : 5.",
   "If CP of x articles = SP of y articles, profit % = (x − y)/y × 100.",
   "Two articles sold at the same price, one at p% gain and the other at p% loss: overall loss = p²/100 %.",
   "Sold in a chain (A to B to C): multiply the multipliers. 20% profit then 25% profit = × 1.2 × 1.25 = × 1.5."],
  [ex("CP ₹800, profit 25%. Find SP.","₹1,000","800 × 125/100 = 1,000."),
   ex("An article is sold for ₹1,080 at a 10% loss. Find CP.","₹1,200","1,080 × 100/90 = 1,200."),
   ex("A shopkeeper marks goods 20% above cost and gives 10% discount. Find profit %.","8%","1.2 × 0.9 = 1.08, so 8% profit."),
   ex("Two articles are sold at ₹1,000 each, one at 20% gain and one at 20% loss. Find overall result.","4% loss","p²/100 = 400/100 = 4% loss."),
   ex("CP of 15 articles = SP of 12 articles. Find profit %.","25%","(15 − 12)/12 × 100 = 25.")],
  [sv("Book practice, 60 minutes max","RSA 'Profit and Loss': first 40 questions of the first exercise."),sv("Previous-year questions","KM 'Profit and Loss': 25 questions, 45 seconds each."),sv("App drill",None,dr("quant","Profit & Loss",20,15))]),
 part("Part 2: Discount and marked price",
  [rd(RSA,"Chapter 'Discount' (and the discount section of Profit & Loss)"),rd(KM,"Chapter 'Discount': first 10 solved questions")],
  ["Discount is always on Marked Price (MP). SP = MP × (100 − d)/100.",
   "Successive discounts a% and b%: single equivalent = a + b − ab/100. 20% and 10% = 28%.",
   "To find MP when profit and discount are given: CP → SP (profit) → MP = SP × 100/(100 − d).",
   "Discount % = (MP − SP)/MP × 100.",
   "Trick: if a trader gives d% discount and still earns profit p%, markup % = (100 + p)/(100 − d) × 100 − 100."],
  [ex("MP ₹2,500, discount 12%. Find SP.","₹2,200","2,500 × 88/100 = 2,200."),
   ex("A trader gets 20% profit after a 10% discount on MP. CP is ₹900. Find MP.","₹1,200","SP = 900 × 1.2 = 1,080. MP = 1,080/0.9 = 1,200."),
   ex("Single discount equal to successive 15% and 20%?","32%","15 + 20 − 3 = 32."),
   ex("An article marked ₹500 is sold at ₹425. Find discount %.","15%","75/500 × 100 = 15.")],
  [sv("Book practice, 60 minutes max","RSA 'Discount': first 30 questions."),sv("Previous-year questions","KM 'Discount': 20 questions."),sv("App drill",None,dr("quant","Discount",15,12))]),
 part("Part 3: Dishonest dealing and chains",
  [rd(RSA,"Profit and Loss: false weights and successive transaction questions"),rd(KM,"Chapter 'Profit and Loss': questions 26 to 50")],
  ["False weight: gain % = (True weight − False weight)/False weight × 100 (when sold at cost).",
   "Equation method: write CP as 100%, then everything else as % of CP. If an extra ₹x changes the result from −a% to +b%, then (a + b)% of CP = x.",
   "Chain deals: CP of first = Final price / (multiplier 1 × multiplier 2)."],
  [ex("A shopkeeper uses a 900 g weight for 1 kg and sells at cost. Find gain %.","11.11%","100/900 × 100 = 11.11."),
   ex("Selling at 5% loss. If SP were ₹100 more, it would be a 5% gain. Find CP.","₹1,000","10% of CP = 100, so CP = 1,000."),
   ex("A sells to B at 20% profit, B sells to C at 25% profit. C pays ₹1,500. Find A's CP.","₹1,000","1,500 / (1.25 × 1.2) = 1,000."),
   ex("SP ₹480 gives 20% loss. What SP gives 10% gain?","₹660","CP = 480/0.8 = 600. SP = 600 × 1.1 = 660.")],
  [sv("Book practice, 60 minutes max","RSA 'Profit and Loss': next 30 questions (harder exercise)."),sv("Previous-year questions","KM 'Profit and Loss': 20 more questions."),sv("App drill",None,dr("quant","Profit & Loss",20,15,"85%"))])]),
unit("Reasoning: Coding-decoding, alphabet tests",[
 part("Part 1: Letter coding",
  [rd(RV,"Chapter 'Coding-Decoding': letter coding"),rd(KR,"Chapter 'Coding-Decoding': first 15 questions")],
  ["Write A=1, B=2 ... Z=26. Memorise EJOTY (5, 10, 15, 20, 25).",
   "Opposite letter of position n is 27 − n (A↔Z, B↔Y, F↔U). Position from the right = 27 − position from the left.",
   "Check shift (+1, +2, −1), reverse alphabet, and alternating shifts (+1, −1, +2, −2).",
   "Compare the first coded word letter by letter before choosing; do not guess from the first letter alone."],
  [ex("If MOON is coded NPPO, how is STAR coded?","TUBS","Each letter +1."),ex("Opposite letter of F?","U","27 − 6 = 21 = U."),
   ex("If CAT = 24, find DOG (sum of letter positions).","26","D4 + O15 + G7 = 26."),ex("Which letter is 7th to the right of the 12th from the left?","S","12 + 7 = 19 = S.")],
  [sv("Book practice, 30 minutes","RV 'Coding-Decoding': 30 letter-coding questions."),sv("Previous-year questions","KR: 20 questions."),sv("App drill",None,dr("reasoning","Coding-Decoding",20,12))]),
 part("Part 2: Number and reverse-alphabet coding",
  [rd(RV,"Chapter 'Coding-Decoding': number and substitution coding"),rd(KR,"Chapter 'Coding-Decoding': questions 16 to 35")],
  ["Reverse alphabet code: A=Z, B=Y ... so CAT becomes XZG.",
   "Number coding: add letter positions, or each letter becomes its position or its square.",
   "Substitution: a word is replaced by another word. Find which word stands for which code by comparing two sentences with one common word."],
  [ex("If A=Z, B=Y, how is CAT written?","XZG","C→X, A→Z, T→G."),ex("If 'good red apple' = 'se na ki' and 'red big ball' = 'na po lu', what is the code for 'red'?","na","'Red' is the common word and 'na' the common code."),
   ex("If A=1, B=2, ..., find BAD.","7","2 + 1 + 4 = 7.")],
  [sv("Book practice, 30 minutes","RV: 30 questions of number and substitution coding."),sv("Previous-year questions","KR: 20 questions."),sv("App drill",None,dr("reasoning","Coding-Decoding",20,12))]),
 part("Part 3: Alphabet tests",
  [rd(RV,"Chapter 'Alphabet Test'"),rd(KR,"Chapter 'Alphabet Test': first 20 questions")],
  ["Count between two letters: positions difference − 1. Between D (4) and N (14): 9 letters.",
   "n-th to the left of position p = p − n. n-th to the right = p + n.",
   "Questions on rearranged words: write position numbers under each letter first."],
  [ex("How many letters lie between D and N?","9","14 − 4 − 1 = 9."),ex("Which letter is 5th to the left of the 15th from the left?","J","15 − 5 = 10 = J."),ex("Which letter is 9th from the right end?","R","27 − 9 = 18 = R.")],
  [sv("Book practice, 30 minutes","RV 'Alphabet Test': 30 questions."),sv("Previous-year questions","KR: 20 questions."),sv("App drill",None,dr("reasoning","Alphabet",15,10))])]),
unit("English: Articles, prepositions, error spotting",[
 part("Part 1: Articles",
  [rd(WM,"Chapter 'The Article'"),rd(SB,"Chapter 'Articles'")],
  ["'A' before a consonant SOUND (a university, a European, a one-rupee note). 'An' before a vowel SOUND (an hour, an honest man, an MBA).",
   "'The' for specific or unique things: the sun, the Ganga, the Himalayas, the Gita, the Times of India, the poor, the best.",
   "No article before proper names, languages, meals, games, subjects in general (English, lunch, cricket).",
   "'The' with musical instruments: She plays the violin. No article with games: He plays cricket.",
   "'A few' = some. 'Few' = hardly any. 'A little' = some. 'Little' = hardly any."],
  [ex("He is ___ honest man.","an","Honest starts with a vowel sound."),ex("___ Ganga is a holy river.","The","Rivers take 'the'."),ex("He is ___ European.","a","European begins with a /y/ sound.")],
  [sv("Book practice, 45 minutes","WM 'The Article': all short exercises."),sv("App drill",None,dr("english","Articles",6,6,"85%")),sv("App drill: error spotting",None,dr("english","Error Spotting",8,8))]),
 part("Part 2: Prepositions",
  [rd(WM,"Chapter 'The Preposition'"),rd(SB,"Chapter 'Prepositions'")],
  ["Time: at 5 pm, at night, on Monday, on 15 August, in 2020, in the morning, in March.",
   "Place: at the station (point), in Delhi (inside), on the table (surface).",
   "Between = two things. Among = more than two. Since = point in time. For = period of time.",
   "Fixed pairs: good at, fond of, afraid of, accused of, suffering from, married to, interested in, congratulate on, prefer X to Y, senior to, junior to, angry with a person / at a thing.",
   "By = agent or deadline (by 5 pm). With = instrument (cut with a knife)."],
  [ex("She is fond ___ music.","of","Fond of."),ex("He was born ___ 15 August 1990.","on","On with dates."),ex("They divided the sweets ___ the three children.","among","More than two."),ex("He congratulated me ___ my success.","on","Congratulate on.")],
  [sv("Book practice, 45 minutes","WM 'The Preposition': exercises (about 40 sentences)."),sv("App drill",None,dr("english","Prepositions",9,8,"85%"))]),
 part("Part 3: Error spotting method",
  [rd(SB,"Chapter 'Spotting Errors': read the full method and rules"),rd(WM,"Revise concord, tense, pronoun and preposition chapters quickly")],
  ["Read the sentence in its four parts. Most errors are in ONE of these: subject-verb agreement, tense, preposition, article, pronoun case, adjective/adverb, word order.",
   "Check each part in this order: verb with subject, tense clue words (yesterday, since), preposition after the verb, article before the noun.",
   "'Less' for uncountable (less water), 'fewer' for countable (fewer people). 'Many' countable, 'much' uncountable.",
   "'Each other' for two, 'one another' for more than two. 'Neither' for two, 'none' for more.",
   "No double comparison: not 'more better' or 'most unkindest'.",
   "If every part seems right, the answer is usually 'No error' (about 1 in 5 questions)."],
  [ex("Find the error: 'He is (a) more taller (b) than his brother (c).'","'more taller'","Double comparison. Use 'taller'."),ex("Find the error: 'Neither of the boys (a) have finished (b) their homework (c).'","'have'","'Neither' is singular, so 'has'."),
   ex("Find the error: 'She has been working (a) here since (b) five years (c).'","'since'","'For' goes with a period.")],
  [sv("Book practice, 45 minutes","SB 'Spotting Errors': 40 sentences, 40 seconds each."),sv("App drill",None,dr("english","Error Spotting",8,8))])]),
unit("GA: Indian Polity II (Union and State government)",[
 part("Part 1: President, Vice-President, PM and Council of Ministers",
  [rd(LX,"Chapters 'President', 'Vice-President', 'Prime Minister', 'Central Council of Ministers'"),rd(NC,"Chapter 4 'Executive' (free at ncert.nic.in)")],
  ["President: Article 52. Elected by an electoral college (Art 54) of elected MPs and MLAs. Minimum age 35. Term 5 years. Oath by the Chief Justice of India.",
   "Vice-President: Article 63. Ex-officio Chairman of Rajya Sabha (Art 64). Elected by members of both Houses (Art 66).",
   "PM: Article 75. Appointed by the President; leader of the majority party in Lok Sabha. Council of Ministers is collectively responsible to Lok Sabha (Art 75(3)).",
   "President can issue ordinances (Art 123) when Parliament is not in session; they must be approved within 6 weeks of reassembly.",
   "Emergencies: Art 352 National, Art 356 President's Rule in a State, Art 360 Financial.",
   "Pardoning power of the President: Art 72."],
  [ex("Who administers the President's oath?","Chief Justice of India"),ex("Which Article gives the President power to make ordinances?","Article 123"),ex("To whom is the Council of Ministers collectively responsible?","Lok Sabha"),ex("Minimum age to be President?","35 years")],
  [sv("Make a one-page chart","Columns: Post / Article / Elected by / Term / Minimum age / Oath by. Fill from the notes and cover and recite."),sv("App drill",None,dr("ga","Polity",15,10))]),
 part("Part 2: Parliament and the Judiciary",
  [rd(LX,"Chapters 'Parliament', 'Parliamentary Committees' (skim), 'Supreme Court', 'High Court'"),rd(NC,"Chapters 5 'Legislature' and 6 'Judiciary'")],
  ["Lok Sabha: maximum 550 (530 States + 20 UTs); term 5 years; Speaker elected by its members. Rajya Sabha: maximum 250 (238 elected + 12 nominated); permanent House; one-third retire every 2 years; Vice-President is its Chairman.",
   "Money Bill: introduced only in Lok Sabha (Art 110). Rajya Sabha can only recommend changes within 14 days.",
   "Joint sitting (Art 108) presided over by the Speaker. Never used for a Money Bill or Constitutional amendment.",
   "Supreme Court: Art 124; retirement age 65; original, appellate, advisory (Art 143) jurisdiction. High Courts: Art 214; retirement age 62.",
   "Judges are removed by impeachment: a special majority in both Houses.",
   "Public Interest Litigation (PIL): introduced by the Supreme Court; any citizen can file."],
  [ex("Where can a Money Bill be introduced?","Lok Sabha only"),ex("Maximum strength of Rajya Sabha?","250"),ex("Retirement age of Supreme Court judges?","65 years"),ex("Which Article allows the President to take the Supreme Court's advice?","Article 143")],
  [sv("Make a chart","Lok Sabha vs Rajya Sabha: strength, term, presiding officer, special powers."),sv("App drill",None,dr("ga","Polity",15,10))]),
 part("Part 3: State government and Panchayati Raj",
  [rd(LX,"Chapters 'Governor', 'Chief Minister', 'State Legislature', 'Panchayati Raj'"),rd(NC,"Chapter 8 'Local Governments'")],
  ["Governor: Art 153. Appointed by the President; 5-year term; must be 35 or older. Chief Minister is appointed by the Governor and is collectively responsible to the Legislative Assembly (Art 164).",
   "Governor's discretionary powers: reserving a Bill for the President (Art 200), recommending President's Rule (Art 356).",
   "State legislature: Legislative Assembly (60 to 500 members), Legislative Council in 6 states (Andhra Pradesh, Telangana, Bihar, Karnataka, Maharashtra, Uttar Pradesh).",
   "Panchayati Raj: 73rd Amendment 1992, in force 1993, Part IX, Articles 243 to 243O, 11th Schedule. Three tiers: Gram Panchayat, Panchayat Samiti, Zila Parishad. 5-year term; reservation for women (one-third).",
   "Municipalities: 74th Amendment, Part IXA, 12th Schedule.",
   "Balwant Rai Mehta Committee (1957) recommended a three-tier Panchayati Raj."],
  [ex("Which Amendment gave constitutional status to Panchayati Raj?","73rd Amendment"),ex("Which Article deals with President's Rule in a State?","Article 356"),ex("Which Schedule lists Panchayat subjects?","11th Schedule"),ex("Who appoints the Chief Minister?","The Governor")],
  [sv("Make a chart","73rd vs 74th Amendment: part, articles, schedule, bodies."),sv("App drill",None,dr("ga","Polity",15,10))])])
)
